import{_ as s,o as a,c as t,ax as i}from"./chunks/framework.Bnt0oLax.js";const u=JSON.parse('{"title":"Test Connectors","description":"Run a Connector against your tenant from the CLI to verify request shape, auth, and payload rendering before you use it from a widget.","frontmatter":{"description":"Run a Connector against your tenant from the CLI to verify request shape, auth, and payload rendering before you use it from a widget."},"headers":[],"relativePath":"cli/test-connectors.md","filePath":"cli/test-connectors.md"}'),n={name:"cli/test-connectors.md"};function r(o,e,d,h,l,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/cli/test-connectors.md for this page in Markdown format</div><h1 id="test-connectors" tabindex="-1">Test Connectors <a class="header-anchor" href="#test-connectors" aria-label="Permalink to &quot;Test Connectors&quot;">​</a></h1><p>Use this guide when you want to exercise a Connector end-to-end from your terminal — inspect the outgoing request, confirm the tenant returns the response shape you expect, and iterate on request parameters without wiring the Connector into a widget first.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>An active session — see <a href="./authenticate.html">Authenticate</a></li><li>Either a local Connector defined under <code>widgets/&lt;widget&gt;/connectors.json</code>, or a Connector already deployed to your tenant</li></ul><h2 id="run-a-connector" tabindex="-1">Run a Connector <a class="header-anchor" href="#run-a-connector" aria-label="Permalink to &quot;Run a Connector&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connector</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revenue-feed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Every run reports where the Connector was resolved from:</p><ul><li><code>source: local</code> — the Connector was found under <code>widgets/*/connectors.json</code> in your project</li><li><code>source: remote</code> — the Connector was fetched from the tenant your session is paired with</li></ul><p>Resolution is <strong>local-first</strong>. If a name matches a local Connector, <code>gsds</code> uses that even when the tenant has a Connector by the same name — this lets you iterate locally without publishing.</p><h2 id="provide-a-request-body" tabindex="-1">Provide a request body <a class="header-anchor" href="#provide-a-request-body" aria-label="Permalink to &quot;Provide a request body&quot;">​</a></h2><p>Pass a JSON body from a file. <code>--payload</code> accepts <strong>file references only</strong>, prefixed with <code>@</code>, and the file must contain valid JSON.</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connector</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revenue-feed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --payload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @body.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Inline JSON is rejected — put the payload in a file and reference it.</p><h2 id="set-query-and-path-parameters" tabindex="-1">Set query and path parameters <a class="header-anchor" href="#set-query-and-path-parameters" aria-label="Permalink to &quot;Set query and path parameters&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connector</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revenue-feed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --query</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> limit=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --query</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cursor=abc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connector</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --path-param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user_id=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">42</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Repeat <code>--query</code> and <code>--path-param</code> for each parameter.</p><h2 id="see-the-rendered-upstream-request" tabindex="-1">See the rendered upstream request <a class="header-anchor" href="#see-the-rendered-upstream-request" aria-label="Permalink to &quot;See the rendered upstream request&quot;">​</a></h2><p>Add <code>--verbose</code> to print the request <code>gsds</code> sends upstream, after <strong>Payload Templates</strong> have been rendered and headers applied. Use this when a Connector &quot;looks right&quot; locally but returns an unexpected response.</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connector</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revenue-feed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="where-runs-are-captured" tabindex="-1">Where runs are captured <a class="header-anchor" href="#where-runs-are-captured" aria-label="Permalink to &quot;Where runs are captured&quot;">​</a></h2><p>Every run is written under <code>.gsds/</code> in your project root, with sensitive request headers redacted. <code>gsds init</code> gitignores <code>.gsds/</code> for you.</p><p>Use the capture directory to compare runs across changes, share reproduction cases without leaking credentials, and diff request shape after editing a Connector.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li><strong>Composite Connectors cannot be tested.</strong> <code>gsds connector test</code> runs a single Connector; composite orchestration happens at request time inside a widget. To validate a composite, test each leaf Connector individually.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Drive <code>gsds connector test --json</code> from CI or an AI agent in <a href="./automate-with-ci-and-ai.html">Automate with CI and AI</a></li><li>Look up every flag in the <a href="./reference/commands.html">Command reference</a></li><li>Review the Connector data model in <a href="/docs/connectors/">Connectors</a></li></ul>`,27)])])}const k=s(n,[["render",r]]);export{u as __pageData,k as default};
